create table if not exists public.timeline_daw_private_transients(owner_id uuid not null references auth.users(id) on delete cascade,source_checksum text not null,sample_rate integer not null,frame_count bigint not null,markers jsonb not null default '[]',updated_at timestamptz not null default now(),primary key(owner_id,source_checksum));alter table public.timeline_daw_private_transients enable row level security;create policy timeline_daw_private_transients_owner_all on public.timeline_daw_private_transients for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
